import { APIError } from 'payload';
const PART_SIZE = 64 * 1024 * 1024 // 64MB per part
;
const MAX_FILE_SIZE_BEFORE_MULTIPART = 100 * 1024 * 1024 // 100MB
;
/** Uploads file bytes to `fileKey`, with a multipart upload for large files. */ export async function uploadFileData({ client, collectionId, fileData, fileKey, fileSize = fileData.length, mimeType }) {
    if (fileSize > MAX_FILE_SIZE_BEFORE_MULTIPART) {
        await uploadMultipart({
            client,
            collectionId,
            fileData,
            fileKey,
            mimeType
        });
    } else {
        await uploadSingleFile({
            client,
            collectionId,
            fileData,
            fileKey,
            mimeType
        });
    }
}
async function uploadSingleFile({ client, collectionId, fileData, fileKey, mimeType }) {
    const { data, error, response } = await client.POST('/api/v0/uploads/sign', {
        body: {
            collectionId,
            contentType: mimeType,
            expiresIn: 3600,
            filename: fileKey
        }
    });
    if (error) {
        throw new APIError(`Failed to get presigned upload URL: ${error.message}`, response.status, {
            code: error.code
        });
    }
    if (!data) {
        throw new Error('No response while getting presigned upload URL');
    }
    const uploadResponse = await fetch(data.url, {
        // TS's BodyInit type rejects Buffer<ArrayBufferLike>; wrap as Uint8Array
        // (a valid ArrayBufferView) — byte-identical.
        body: new Uint8Array(fileData),
        headers: {
            'Content-Type': mimeType
        },
        method: 'PUT'
    });
    if (!uploadResponse.ok) {
        throw new Error(`Failed to upload to S3: ${uploadResponse.status} ${uploadResponse.statusText}`);
    }
}
async function uploadMultipart({ client, collectionId, fileData, fileKey, mimeType }) {
    const { data: initiateData, error: initiateError, response: initiateResponse } = await client.POST('/api/v0/uploads/multipart/initiate', {
        body: {
            collectionId,
            contentType: mimeType,
            filename: fileKey
        }
    });
    if (initiateError) {
        throw new APIError(`Failed to initiate multipart upload: ${initiateError.message}`, initiateResponse.status, {
            code: initiateError.code
        });
    }
    if (!initiateData) {
        throw new Error('No response while initiating multipart upload');
    }
    const { uploadId } = initiateData;
    try {
        const numParts = Math.ceil(fileData.length / PART_SIZE);
        const partNumbers = Array.from({
            length: numParts
        }, (_, i)=>i + 1);
        const { data: partsData, error: partsError, response: partsResponse } = await client.POST('/api/v0/uploads/multipart/parts', {
            body: {
                collectionId,
                expiresIn: 3600,
                filename: fileKey,
                partNumbers,
                uploadId
            }
        });
        if (partsError) {
            throw new APIError(`Failed to get part URLs: ${partsError.message}`, partsResponse.status, {
                code: partsError.code
            });
        }
        if (!partsData) {
            throw new Error('No response while getting part URLs');
        }
        const { parts } = partsData;
        if (!parts || !Array.isArray(parts)) {
            throw new Error('Invalid response from part URLs endpoint: parts is not an array');
        }
        const uploadedParts = await Promise.all(parts.map(async ({ partNumber, url })=>{
            const start = (partNumber - 1) * PART_SIZE;
            const end = Math.min(start + PART_SIZE, fileData.length);
            const partData = fileData.slice(start, end);
            const uploadResponse = await fetch(url, {
                body: partData,
                headers: {
                    'Content-Type': mimeType
                },
                method: 'PUT'
            });
            const etag = uploadResponse.headers.get('ETag');
            if (!etag) {
                throw new Error(`No ETag returned for part ${partNumber}`);
            }
            return {
                ETag: etag,
                PartNumber: partNumber
            };
        }));
        const { error: completeError, response: completeResponse } = await client.POST('/api/v0/uploads/multipart/complete', {
            body: {
                collectionId,
                filename: fileKey,
                parts: uploadedParts,
                uploadId
            }
        });
        if (completeError) {
            throw new APIError(`Failed to complete multipart upload: ${completeError.message}`, completeResponse.status, {
                code: completeError.code
            });
        }
    } catch (error) {
        try {
            await client.POST('/api/v0/uploads/multipart/abort', {
                body: {
                    collectionId,
                    filename: fileKey,
                    uploadId
                }
            });
        } catch  {
        // Ignore abort errors
        }
        throw error;
    }
}
